"""Spoken project tour: text comes from data/narration.md and is read aloud by text-to-speech.

Two speech paths, same script:
  * Browser speech synthesis (Web Speech API) - usually the best voices, chosen/tuned in the player, no server work.
  * A pre-rendered recording (assets/tour.mp3 or tour.wav, generated by scripts/generate_narration_audio.py) as an offline fallback.
"""
from __future__ import annotations

import json
import re
from pathlib import Path

import streamlit as st
import streamlit.components.v1 as components

from services.narration import load_sections, word_count

ASSETS = Path(__file__).resolve().parent.parent / "assets"

_PLAYER = """
<style>
*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui,Segoe UI,sans-serif;color:#eef1ff;background:transparent}
.wrap{display:grid;grid-template-columns:1.25fr 1fr;gap:16px}@media(max-width:820px){.wrap{grid-template-columns:1fr}}
.panel{background:rgba(16,22,48,.62);border:1px solid rgba(160,175,255,.22);border-radius:18px;padding:16px 18px;backdrop-filter:blur(14px);box-shadow:0 10px 36px rgba(2,4,20,.45)}
.bar{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-bottom:12px}
button{cursor:pointer;border:0;color:#fff;font-weight:650;border-radius:12px;padding:10px 16px;font-size:14px;background:linear-gradient(120deg,#8b7bff,#5b8cff 55%,#34d4ff);
 box-shadow:0 8px 22px rgba(91,110,255,.38);transition:.18s}button:hover{transform:translateY(-2px);filter:brightness(1.1)}
button.ghost{background:rgba(139,123,255,.18);box-shadow:none;border:1px solid rgba(160,175,255,.25)}
select,input[type=range]{accent-color:#8b7bff}select{background:rgba(8,12,30,.8);color:#eef1ff;border:1px solid rgba(160,175,255,.3);border-radius:10px;padding:8px;max-width:230px}
label{font-size:12px;color:#a9b2d6}
.now{font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:#7fe3ff;margin:4px 0}
h2{margin:0 0 8px;font-size:22px;background:linear-gradient(92deg,#fff,#b9b1ff 50%,#72e6ff);-webkit-background-clip:text;background-clip:text;color:transparent}
#text{font-size:16px;line-height:1.65;color:#dfe4ff;min-height:150px}#text span{padding:1px 2px;border-radius:5px;transition:background .25s}
#text span.on{background:rgba(139,123,255,.38);box-shadow:0 0 0 2px rgba(139,123,255,.18)}
.prog{height:6px;border-radius:99px;background:rgba(160,175,255,.18);overflow:hidden;margin:12px 0 4px}.prog>div{height:100%;width:0;background:linear-gradient(90deg,#8b7bff,#34d4ff);transition:width .4s}
ol{list-style:none;margin:0;padding:0;max-height:470px;overflow:auto}
li{display:flex;gap:10px;align-items:center;padding:9px 11px;border-radius:12px;cursor:pointer;font-size:14px;color:#cfd6ff;transition:.15s}
li:hover{background:rgba(139,123,255,.16)}li.on{background:linear-gradient(120deg,rgba(139,123,255,.42),rgba(52,212,255,.22));color:#fff;font-weight:650}
li b{width:24px;height:24px;border-radius:50%;display:grid;place-items:center;font-size:12px;background:rgba(160,175,255,.2);flex:none}li.on b{background:#8b7bff}
.eq{display:inline-flex;gap:3px;align-items:flex-end;height:18px;margin-left:8px;vertical-align:middle}.eq i{width:4px;background:#34d4ff;border-radius:2px;height:5px}
.playing .eq i{animation:eq .9s ease-in-out infinite}.eq i:nth-child(2){animation-delay:.2s!important}.eq i:nth-child(3){animation-delay:.4s!important}.eq i:nth-child(4){animation-delay:.1s!important}
@keyframes eq{50%{height:18px}}.warn{color:#ffc857;font-size:13px;margin-top:8px}
</style>
<div class="wrap" id="root">
 <div class="panel">
  <div class="bar">
   <button id="play">▶ Play tour</button><button class="ghost" id="pause">⏸ Pause</button><button class="ghost" id="stop">⏹ Stop</button>
   <button class="ghost" id="prev">⏮</button><button class="ghost" id="next">⏭</button>
  </div>
  <div class="bar"><label>Voice <select id="voice"></select></label><label>Speed <input id="rate" type="range" min="0.7" max="1.4" step="0.05" value="1"> <span id="rv">1.0×</span></label></div>
  <div class="now" id="now">Ready<span class="eq"><i></i><i></i><i></i><i></i></span></div>
  <h2 id="title"></h2><div id="text"></div>
  <div class="prog"><div id="pb"></div></div><div id="warn" class="warn"></div>
 </div>
 <div class="panel"><div class="now">Chapters</div><ol id="list"></ol></div>
</div>
<script>
const DATA = __DATA__;
const synth = window.speechSynthesis;
const $ = id => document.getElementById(id);
let sec = 0, sen = 0, playing = false, token = 0, voices = [];
DATA.forEach(s => s.sentences = s.text.match(/[^.!?]+[.!?]+|[^.!?]+$/g).map(x => x.trim()));
function renderList(){ $('list').innerHTML = DATA.map((s,i)=>`<li data-i="${i}" class="${i===sec?'on':''}"><b>${i+1}</b>${s.title}</li>`).join('');
  document.querySelectorAll('li').forEach(li => li.onclick = () => { sec = +li.dataset.i; sen = 0; start(); }); }
function renderSection(){ const s = DATA[sec]; $('title').textContent = s.title;
  $('text').innerHTML = s.sentences.map((t,i)=>`<span id="s${i}" class="${i===sen?'on':''}">${t} </span>`).join('');
  $('pb').style.width = ((sec + (sen/ s.sentences.length)) / DATA.length * 100) + '%'; renderList(); }
function setState(p){ playing = p; $('root').classList.toggle('playing', p); $('now').firstChild.textContent = p ? 'Speaking — chapter ' + (sec+1) + ' of ' + DATA.length : 'Paused / ready'; }
function pickVoices(){ voices = synth.getVoices().filter(v => /^en/i.test(v.lang)); const sel = $('voice'); sel.innerHTML = '';
  const score = v => (/natural|neural|online/i.test(v.name)?4:0) + (/google|microsoft|samantha|aria|jenny|daniel|karen/i.test(v.name)?2:0) + (/en-(us|gb|in)/i.test(v.lang)?1:0);
  voices.sort((a,b)=>score(b)-score(a)); voices.forEach((v,i)=>{ const o = document.createElement('option'); o.value = i; o.textContent = v.name + ' (' + v.lang + ')'; sel.appendChild(o); });
  if(!voices.length) $('warn').textContent = 'No English voice found in this browser. Use the recorded audio below.'; }
function speak(){ if(!playing) return; const my = ++token; const text = DATA[sec].sentences[sen]; renderSection();
  const u = new SpeechSynthesisUtterance(text); u.rate = +$('rate').value; if(voices[$('voice').value]) u.voice = voices[$('voice').value];
  u.onend = () => { if(my !== token || !playing) return; sen++; if(sen >= DATA[sec].sentences.length){ sec++; sen = 0; if(sec >= DATA.length){ sec = 0; setState(false); renderSection(); $('now').firstChild.textContent='Tour finished — thanks for listening!'; return; } }
    speak(); };
  u.onerror = () => { if(my === token) setState(false); }; synth.cancel(); synth.speak(u); }
function start(){ if(!synth){ $('warn').textContent='This browser has no speech synthesis. Use the recorded audio below.'; return; } token++; synth.cancel(); setState(true); speak(); }
$('play').onclick = () => { if(playing) return; start(); };
$('pause').onclick = () => { token++; synth.cancel(); setState(false); };
$('stop').onclick = () => { token++; synth.cancel(); sec = 0; sen = 0; setState(false); renderSection(); };
$('next').onclick = () => { sec = (sec+1) % DATA.length; sen = 0; playing ? start() : renderSection(); };
$('prev').onclick = () => { sec = (sec-1+DATA.length) % DATA.length; sen = 0; playing ? start() : renderSection(); };
$('rate').oninput = () => { $('rv').textContent = (+$('rate').value).toFixed(2).replace(/0$/,'') + '×'; };
$('rate').onchange = () => { if(playing) start(); }; $('voice').onchange = () => { if(playing) start(); };
if(synth){ pickVoices(); synth.onvoiceschanged = pickVoices; } else { $('warn').textContent = 'This browser has no speech synthesis.'; }
renderSection(); setState(false); $('now').firstChild.textContent = 'Ready — press Play';
window.addEventListener('beforeunload', () => synth && synth.cancel());
</script>
"""


def _audio_file() -> Path | None:
    for name in ("tour.mp3", "tour.wav"):
        if (ASSETS / name).exists():
            return ASSETS / name
    return None


def render_tour() -> None:
    sections = load_sections()
    st.markdown("## 🔊 Listen to the project tour")
    st.caption(f"{len(sections)} chapters · about {word_count()} words · the speech is generated from `data/narration.md` — edit that file and the tour changes.")
    html = _PLAYER.replace("__DATA__", json.dumps([{"title": s.title, "text": s.text} for s in sections]))
    if hasattr(st, "iframe"):                       # Streamlit >= 1.6x; components.html is deprecated there
        st.iframe(html, height=600)
    else:
        components.html(html, height=600, scrolling=False)
    audio = _audio_file()
    st.markdown("##### Offline recording")
    if audio:
        st.audio(audio.read_bytes(), format="audio/mp3" if audio.suffix == ".mp3" else "audio/wav")
        st.caption("Pre-rendered with the local espeak-ng engine (robotic but works with no browser voices). Regenerate or upgrade it with "
                   "`python scripts/generate_narration_audio.py --engine espeak|pyttsx3|gtts`.")
    else:
        st.info("No pre-rendered audio yet. Run `python scripts/generate_narration_audio.py`.")
    with st.expander("Read the full script"):
        for s in sections:
            st.markdown(f"**{s.title}** — {s.text}")
